package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONObject;import java.util.UUID;
/** Customer sale with immutable capital/profit and work-day FX snapshots. */
public final class AdvancedSaleStore {
 private final CoreStore.DbProvider provider;private final String deviceId;public AdvancedSaleStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public Result sale(String productId,int qty,String customerId,double discount,String currency,String payment,int pointsUsed)throws Exception{if(qty<=0)throw new IllegalArgumentException("الكمية غير صالحة");if(discount<0||!Double.isFinite(discount))throw new IllegalArgumentException("الخصم غير صالح");SQLiteDatabase db=provider.db();db.beginTransaction();try{String name;int before;double price,cost;try(Cursor c=db.rawQuery("SELECT name,quantity,sale_price,cost_price FROM products WHERE product_id=? AND deleted_at IS NULL",new String[]{productId})){if(!c.moveToFirst())throw new IllegalArgumentException("المنتج غير موجود");name=c.getString(0);before=c.getInt(1);price=c.getDouble(2);cost=c.getDouble(3);}if(before<qty)throw new IllegalArgumentException("المخزون غير كافٍ");int points=0;if(!trim(customerId).isEmpty()){try(Cursor c=db.rawQuery("SELECT loyalty_points FROM customers WHERE customer_id=? AND deleted_at IS NULL",new String[]{customerId})){if(!c.moveToFirst())throw new IllegalArgumentException("العميل غير موجود");points=c.getInt(0);}}if(pointsUsed<0||pointsUsed>points)throw new IllegalArgumentException("نقاط العميل غير كافية");double subtotal=price*qty,total=Math.max(0,subtotal-discount),capital=cost*qty,profit=total-capital;long now=System.currentTimeMillis();String iid="sale-"+UUID.randomUUID(),no="S-"+now,cur=currency(currency),pay=payment(payment);ContentValues inv=new ContentValues();inv.put("invoice_id",iid);inv.put("invoice_no",no);inv.put("invoice_type","SALE");inv.put("currency",cur);inv.put("subtotal",subtotal);inv.put("discount",discount);inv.put("total",total);inv.put("payment_method",pay);inv.put("created_at",now);inv.put("updated_at",now);db.insertOrThrow("invoices",null,inv);ContentValues it=new ContentValues();it.put("item_id","item-"+UUID.randomUUID());it.put("invoice_id",iid);it.put("product_id",productId);it.put("description",name);it.put("quantity",qty);it.put("unit_price",price);it.put("total",subtotal);it.put("unit_cost_snapshot",cost);it.put("cost_total_snapshot",capital);it.put("profit_snapshot",profit);it.put("created_at",now);db.insertOrThrow("invoice_items",null,it);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"SALE",iid,cur,total,now);int after=before-qty;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);db.update("products",pv,"product_id=?",new String[]{productId});ContentValues sm=new ContentValues();sm.put("move_id","stock-"+UUID.randomUUID());sm.put("product_id",productId);sm.put("source_type","SALE");sm.put("source_id",iid);sm.put("before_qty",before);sm.put("delta_qty",-qty);sm.put("after_qty",after);sm.put("created_at",now);db.insertOrThrow("stock_moves",null,sm);if(!pay.equals("LATER")){ContentValues cm=new ContentValues();cm.put("move_id","cash-"+UUID.randomUUID());cm.put("source_type","SALE");cm.put("source_id",iid);cm.put("direction","IN");cm.put("amount",total);cm.put("currency",cur);cm.put("payment_method",pay);cm.put("drawer",drawer(pay));cm.put("created_at",now);db.insertOrThrow("cash_moves",null,cm);}if(pointsUsed>0){ContentValues cv=new ContentValues();cv.put("loyalty_points",points-pointsUsed);cv.put("updated_at",now);db.update("customers",cv,"customer_id=?",new String[]{customerId});ContentValues lm=new ContentValues();lm.put("move_id","loyalty-"+UUID.randomUUID());lm.put("customer_id",customerId);lm.put("points",-pointsUsed);lm.put("source_type","SALE");lm.put("source_id",iid);lm.put("created_at",now);db.insertOrThrow("loyalty_moves",null,lm);}JSONObject j=new JSONObject().put("invoiceId",iid).put("invoiceNo",no).put("productId",productId).put("quantity",qty).put("subtotal",subtotal).put("discount",discount).put("total",total).put("currency",cur).put("paymentMethod",pay).put("customerId",trim(customerId)).put("pointsUsed",pointsUsed).put("unitCostSnapshot",cost).put("capitalSnapshot",capital).put("profitSnapshot",profit).put("fxUsdPerUnit",fx.usdPerUnit).put("totalUsdSnapshot",fx.usdAmount).put("fxCapturedAt",fx.capturedAt).put("stockAfter",after).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE,iid,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(iid,no,total,capital,profit,fx.usdAmount,after);}finally{db.endTransaction();}}
 public static final class Result{public final String invoiceId,invoiceNo;public final double total,capital,profit,totalUsd;public final int remainingQty;Result(String id,String n,double t,double c,double p,double u,int q){invoiceId=id;invoiceNo=n;total=t;capital=c;profit=p;totalUsd=u;remainingQty=q;}}
 private static String drawer(String p){if(p.equals("SHAM_CASH"))return "SHAM_CASH";if(p.equals("BANK"))return "BANK";if(p.equals("EXTERNAL"))return "EXTERNAL";return "MAIN";}private static String payment(String v){String x=trim(v).toUpperCase();return x.equals("SHAM_CASH")||x.equals("BANK")||x.equals("EXTERNAL")||x.equals("LATER")?x:"CASH";}private static String currency(String v){String x=trim(v).toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}private static String trim(String v){return v==null?"":v.trim();}
}
